CREATE DATABASE IF NOT EXISTS db_profil_sekolah CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE db_profil_sekolah;

CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,email_verified_at TIMESTAMP NULL,password VARCHAR(255) NOT NULL,remember_token VARCHAR(100) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
INSERT INTO users (name,email,password,created_at,updated_at) VALUES ('Admin','admin@alhidayah.sch.id','$2y$12$vbfkZ82eu11B94u6VnNr2Olw3YfbR0HED./avHQfXufBRrQNIs2ai',NOW(),NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name);

CREATE TABLE IF NOT EXISTS guru (id_guru BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nama_guru VARCHAR(100) NOT NULL,nip VARCHAR(30) NULL,mapel VARCHAR(100) NULL,foto VARCHAR(255) NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS siswa (id_siswa BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nisn VARCHAR(30) NOT NULL,nama_siswa VARCHAR(100) NOT NULL,jenis_kelamin ENUM('Laki-Laki','Perempuan') NOT NULL,tahun_masuk SMALLINT UNSIGNED NOT NULL,foto VARCHAR(255) NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS berita (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,judul VARCHAR(255) NOT NULL,isi TEXT NOT NULL,tanggal DATE NOT NULL,gambar VARCHAR(255) NULL,id_user BIGINT UNSIGNED NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ekstrakulikulers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nama_ekskul VARCHAR(100) NOT NULL,pembina VARCHAR(100) NULL,jadwal_latihan VARCHAR(100) NULL,deskripsi TEXT NULL,gambar VARCHAR(255) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS galeri (id_galeri BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,judul VARCHAR(100) NOT NULL,keterangan TEXT NULL,file VARCHAR(255) NULL,kategori VARCHAR(30) NOT NULL DEFAULT 'Foto',tanggal DATE NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS profil_sekolah (id_profil BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nama_sekolah VARCHAR(150) NOT NULL,kepala_sekolah VARCHAR(150) NULL,foto VARCHAR(255) NULL,logo VARCHAR(255) NULL,npsn VARCHAR(30) NULL,alamat TEXT NULL,kontak VARCHAR(100) NULL,visi_misi TEXT NULL,tahun_berdiri SMALLINT UNSIGNED NULL,deskripsi TEXT NULL) ENGINE=InnoDB;
